-- Claim-safe, deterministic French content. No user account or credential is seeded.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE
    slug = VALUES(slug), title = VALUES(title), summary = VALUES(summary), problem_text = VALUES(problem_text),
    positioning_text = VALUES(positioning_text), blocks_json = VALUES(blocks_json),
    seo_title = VALUES(seo_title), seo_description = VALUES(seo_description), sort_order = VALUES(sort_order);

ON DUPLICATE KEY UPDATE
    slug = VALUES(slug), title = VALUES(title), summary = VALUES(summary), blocks_json = VALUES(blocks_json),
    seo_title = VALUES(seo_title), seo_description = VALUES(seo_description), sort_order = VALUES(sort_order);

ON DUPLICATE KEY UPDATE
    title = VALUES(title), summary = VALUES(summary), blocks_json = VALUES(blocks_json),
    seo_title = VALUES(seo_title), seo_description = VALUES(seo_description), reading_minutes = VALUES(reading_minutes);

ON DUPLICATE KEY UPDATE
    title = VALUES(title), summary = VALUES(summary), verification_notes = VALUES(verification_notes), status = 'draft';

ON DUPLICATE KEY UPDATE value_json = VALUES(value_json), status = VALUES(status), is_sensitive = VALUES(is_sensitive);
